#include "stdafx.h"#include "Client.h"#include <SetDataTypes.h>#include <Connect.h>#include <RsuX.h>#include <rsuNoNames.h>#include <HcdDataTypes_.h>#include <SysDataTypes.h>#include <time.h>#include "HcdPool.h"#include <ConnectHCD.h>#include <HcdMemoryService.h>#pragma comment( lib, "ConnectHCD.lib")bool GetFirstACSObject( );bool GetNextACSObject( DWORD & Type, void ** pData, char Name[256], char Info[256] );bool ShowACSObject( void * pInfo, HWND hMainWnd, char * Name, void * pData );LPCSTR g_szPntsFilePrefix = "РСУ_HCD_";static bool bRegisteredFind = false;nRSUx::SParamInfo RsuConnectParamInfo( LPCSTR pszPointName, LPSTR pszIOtype, LPCSTR pSuffix );extern KHcdPool g_Pool;KNoName g_SharedMemory, g_IoMemory;KClient::KClient( LPSTR _ObjName ) :	IBaseModel ( _ObjName ), m_pHcdSystem( NULL ){  TypeObj = RSU_Obj;}LPCSTR KClient::GetName(){  return ObjName;}int KClient::Init( int ){  LPCSTR pszRealName = ObjName;  size_t prefixLen = strlen(g_szPntsFilePrefix);  if( !_strnicmp(pszRealName, g_szPntsFilePrefix, prefixLen) )    pszRealName += prefixLen;  strcpy_s( m_szObjName, pszRealName );#ifdef _DEBUG  int r = KRsuSharedClient::InitializeServer( "HCD_Server", ObjName, true );#else  int r = KRsuSharedClient::InitializeServer( "HCD_Server", ObjName );#endif  if( r )    return 1;  if( pRegisterFinderACSobj && !bRegisteredFind )  {    bRegisteredFind = true;    pRegisterFinderACSobj( ::GetFirstACSObject, ::GetNextACSObject, ::ShowACSObject);  }  if( pRegisterRsuConnection )    pRegisterRsuConnection( g_szPntsFilePrefix, RsuConnectParamInfo, NULL );  g_Pool.RegisterCB( this );  g_IoMemory = KNoName::Create( "HcdIO", false );  g_SharedMemory = KNoName::Create( "HcdShared", false );  if( !pRegisterHCDstructs )    LoadLibrary("HCDRegisterInRSU.dll");  if( pRegisterHCDstructs )    pRegisterHCDstructs();  m_pHcdSystem = (CHcdSystem*)g_SharedMemory.FindStruct( "Весь Hcd", CHcdSystem::TypeID, 0 );  return 0;}int KClient::Step0(){  return KRsuSharedClient::StepAfterInit();}int KClient::Step1(){  if( m_pHcdSystem )  {    m_pHcdSystem->startTime = time(NULL);    m_pHcdSystem->dModelT = 0;  }  return KRsuSharedClient::StepAfterRestored();}int KClient::StepT(double dt){  if( m_pHcdSystem && pSys )  {    m_pHcdSystem->startTime = pSys->startTime;    m_pHcdSystem->dModelT = pSys->TimeB() ;    m_pHcdSystem->StartStatus = CHcdSystemA::STATUS_START;  }  double dtMs = dt * 3600. * 1000;  return KRsuSharedClient::CalcStep( (int)dtMs );}int KClient::SetData( int TypeData, void * pData ){  switch( TypeData )  {  case sd_SaveRSUParams:    return KRsuSharedClient::ParamsSave( (LPCSTR)pData );  case sd_RestoreRSUParams:    return KRsuSharedClient::ParamsRestore( (LPCSTR)pData );  case sd_SaveRSUState:    return KRsuSharedClient::StateSave( (LPCSTR)pData );  case sd_RestoreRSUState:    return KRsuSharedClient::StateRestore( (LPCSTR)pData );  default:    return -1;  }  return 0;}